	@override String get fav_char_prompt_desc => 'Bitte legen Sie Ihren Lieblingscharakter fest. Wenn Sie dieses Feld leer lassen, können Sie Ihr Passwort in Zukunft nicht mehr zurücksetzen oder Ihr Konto wiederherstellen.';
